package com.example.starter.domain;

/**
 * 业务异常：携带 HTTP 状态码与错误码，由全局异常处理器转换为响应。
 */
public class ApiException extends RuntimeException {

    private final int status;
    private final String code;

    public ApiException(int status, String code, String message) {
        super(message);
        this.status = status;
        this.code = code;
    }

    public int getStatus() {
        return status;
    }

    public String getCode() {
        return code;
    }
}

package com.example.starter.web.dto;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;
import jakarta.validation.constraints.Size;

import java.util.List;

/**
 * 制品版本登记请求。
 *
 * @param requestId    全局唯一写请求ID，用于幂等重放
 * @param name         制品名称
 * @param version      制品版本号，正整数
 * @param dependencies 依赖声明列表，0～10条，可省略
 */
public record RegisterArtifactRequest(
        @NotBlank String requestId,
        @NotBlank String name,
        @NotNull @Positive Integer version,
        @Valid @Size(max = 10) List<DependencyRequest> dependencies
) {
}

package com.example.starter.web.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;

/**
 * 单条依赖声明：被依赖制品名称及闭区间兼容版本 [minVersion, maxVersion]。
 */
public record DependencyRequest(
        @NotBlank String name,
        @NotNull @Positive Integer minVersion,
        @NotNull @Positive Integer maxVersion
) {
}

package com.example.starter.web.dto;

import jakarta.validation.constraints.NotBlank;

/**
 * 制品撤回请求。
 */
public record WithdrawRequest(
        @NotBlank String requestId
) {
}

package com.example.starter.web.dto;

import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;

/**
 * 依赖锁定请求：指定精确根版本及期望的仓库版本。
 */
public record CreateLockRequest(
        @NotBlank String requestId,
        @NotBlank String rootName,
        @NotNull @Positive Integer rootVersion,
        @NotNull @Min(0) Long expectedRepositoryVersion
) {
}

